#![feature(custom_inner_attributes)]
#![verus::verus]

use vstd::prelude::*;

// Given two vectors of 32‐bit floats, produce a new vector that is the
// concatenation of the first followed by the second.
// The result is specified to satisfy:
//   1. result.len() == a.len() + b.len()
//   2. ∀ i < a.len(): result[i] == a[i]
//   3. ∀ j < b.len(): result[a.len() + j] == b[j]
verus! {

    fn hstack(a: Vec<f32>, b: Vec<f32>) -> Vec<f32>
        ensures result.len() == a.len() + b.len()
        ensures forall |i: nat| i < a.len() as nat
            ==> result[i as usize] == a[i as usize]
        ensures forall |j: nat| j < b.len() as nat
            ==> result[a.len() as usize + j as usize] == b[j as usize]
    {
        // Pre‐allocate to avoid re-allocation during pushes
        let mut res: Vec<f32> = Vec::new();
        res.reserve(a.len() + b.len());

        // Push all elements from `a`
        let mut i: usize = 0;
        while i < a.len() {
            // Loop invariants to help the verifier track progress
            invariant i <= a.len();
            invariant res.len() == i;
            invariant forall |k: nat| k < i as nat
                ==> res[k as usize] == a[k as usize];

            res.push(a[i]);
            i += 1;
        }

        // Push all elements from `b`
        let mut j: usize = 0;
        while j < b.len() {
            invariant j <= b.len();
            // After pushing j elements of b, the total length is a.len() + j
            invariant res.len() == a.len() + j;
            // Elements from `a` are already in place
            invariant forall |k: nat| k < a.len() as nat
                ==> res[k as usize] == a[k as usize];
            // Elements from `b` so far are in positions a.len()..a.len()+j
            invariant forall |k: nat| k < j as nat
                ==> res[a.len() as usize + k as usize] == b[k as usize];

            res.push(b[j]);
            j += 1;
        }

        res
    }

}